import{_ as u,a0 as a,w as s,s as r,ao as l,I as p,x as o,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"使用谷歌文档在 Ubuntu 中对文本进行语音识别 | LCTT x X-CMD","titleTemplate":false,"description":"使用谷歌文档在 Ubuntu 中对文本进行语音识别 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用谷歌文档在 Ubuntu 中对文本进行语音识别 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用谷歌文档在 Ubuntu 中对文本进行语音识别 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs","title":"使用谷歌文档在 Ubuntu 中对文本进行语音识别","tag":"202210","desc":""},"relativePath":"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs.md","filePath":"[post].md"}'),d={name:"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs.md"};function g(m,t,b,h,w,x){const n=a("Link");return s(),r("div",null,[t[24]||(t[24]=l('<h1 id="使用谷歌文档在-ubuntu-中对文本进行语音识别" tabindex="-1">使用谷歌文档在 Ubuntu 中对文本进行语音识别 <a class="header-anchor" href="#使用谷歌文档在-ubuntu-中对文本进行语音识别" aria-label="Permalink to “使用谷歌文档在 Ubuntu 中对文本进行语音识别”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/04/222403dhey2zwn1442u3n1.jpg" alt=""></p><blockquote><p>这就是在包括 Ubuntu 在内的 Linux 系统中将语音转换为文本的方法。</p></blockquote><p>Linux 系统中可用的语音识别软件不多，尤其是原生桌面应用。有一些可用的应用使用 IBM Watson 和其他 API 将语音转换为文本，但它们的用户交互不友好，需要一些复杂的用户交互，例如用相应的语言进行一些编程或脚本编写。</p><p>但是，没有多少用户知道 <ruby>谷歌文档<rt>Google Docs</rt></ruby> 使用自己的 AI 技术提供了高级语音识别，它可以通过 Chrome 访问谷歌文档使用。</p><p>任何用户都可以使用此功能将语音转换为文本，而无需高级计算机知识。谷歌文档的这个功能最好的一点是你可以在任何 Ubuntu 衍生版或任何支持 Chrome 的 Linux 发行版中使用它。</p><p>让我们看看如何在 Ubuntu 中启用它。</p><h3 id="如何将语音转换为文本" tabindex="-1">如何将语音转换为文本 <a class="header-anchor" href="#如何将语音转换为文本" aria-label="Permalink to “如何将语音转换为文本”">​</a></h3>',8)),p("p",null,[t[1]||(t[1]=o("先决条件是你应该在系统中安装 Chrome 并拥有谷歌帐户。如果你没有安装 Chrome，你可以访问 ",-1)),e(n,{href:"https://www.google.com/chrome"},{default:i(()=>[...t[0]||(t[0]=[o("此链接",-1)])]),_:1}),t[2]||(t[2]=o(" 并下载、安装 Chrome。",-1))]),p("p",null,[t[4]||(t[4]=o("此外，如果你没有谷歌帐户，你可以使用 ",-1)),e(n,{href:"https://accounts.google.com"},{default:i(()=>[...t[3]||(t[3]=[o("此链接",-1)])]),_:1}),t[5]||(t[5]=o(" 免费创建一个。",-1))]),t[25]||(t[25]=p("h4",{id:"步骤-1",tabindex:"-1"},[o("步骤 1 "),p("a",{class:"header-anchor",href:"#步骤-1","aria-label":"Permalink to “步骤 1”"},"​")],-1)),p("p",null,[t[7]||(t[7]=o("从 Chrome 打开 ",-1)),e(n,{href:"https://docs.google.com"},{default:i(()=>[...t[6]||(t[6]=[o("https://docs.google.com",-1)])]),_:1}),t[8]||(t[8]=o(" 并创建一个空白文档。",-1))]),t[26]||(t[26]=l('<p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Create-an-empty-doc.png" alt="创建一个空文档"></p><h4 id="步骤-2" tabindex="-1">步骤 2 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to “步骤 2”">​</a></h4><p>加载空白文档后，从菜单中单击“工具 &gt; 语音输入”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Enable-Voice-Typing.png" alt="启用语音输入"></p><h4 id="步骤-3" tabindex="-1">步骤 3 <a class="header-anchor" href="#步骤-3" aria-label="Permalink to “步骤 3”">​</a></h4><p>在左侧，你可以看到一个麦克风图标。单击麦克风图标，Chrome 会首次要求允许通过浏览器访问麦克风。单击允许。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Click-the-mic.png" alt="点击麦克风"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Allow-Docs-to-access-Mic.png" alt="允许文档访问麦克风"></p><p>默认情况下，它使用你的系统语言作为语音的检测语言，同时将其转换为文本；但是，你可以根据可用的语言列表将其更改为所需的任何语言。到目前为止，谷歌文档支持和识别超过 60 多种语言，同时将它们转换为文本。</p><h4 id="步骤-4" tabindex="-1">步骤 4 <a class="header-anchor" href="#步骤-4" aria-label="Permalink to “步骤 4”">​</a></h4><p>单击允许后，麦克风图标将变为橙色，现在它已准备好接受或识别你的声音。开始说任何你想说的话，瞧！你将看到你的演讲被转换为文本并写入文档。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Voice-to-Text-In-action.png" alt="正在进行语音转文字"></p><p>完成了。你已通过谷歌 Chrome 和谷歌文档在 Ubuntu 中成功地将语音转换为文本。</p><p>所有 Linux 用户都可以免费使用这个很棒的功能。如果你知道其他可以在 Linux 中将语音转换为文本的应用，请在下方的评论区发表评论。另外，让我知道你是否觉得这篇文章有用。</p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>如果上述功能在你的浏览器中不起作用，请务必查看以下内容。</p><ul><li>打开设置窗口（在 Ubuntu 或其他发行版的 GNOME 桌面中）。</li><li>转到“隐私 &gt; 麦克风”。</li><li>并确保它已启用。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Check-Microphone-settings-in-Ubuntu.jpg" alt="检查 Ubuntu 中的麦克风设置"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>虽然，最近有一种基于云的解决方案可用，例如 Amazon Polly 等。但它们的价格很高。另外还需要一些有用的知识。</p><p>而谷歌 Chrome 的内置语音识别功能简单易用。虽然它有点慢，但它可以为普通用户完成工作。</p><p>也就是说，我希望本指南可以帮助你将语音转换为文本，如果你知道这样的免费应用，请在评论区告诉我。</p><hr>',23)),p("p",null,[t[10]||(t[10]=o("via: ",-1)),e(n,{href:"https://www.debugpoint.com/speech-recognition-to-text-in-linux-ubuntu-using-google-docs/"},{default:i(()=>[...t[9]||(t[9]=[o("https://www.debugpoint.com/speech-recognition-to-text-in-linux-ubuntu-using-google-docs/",-1)])]),_:1})]),p("p",null,[t[15]||(t[15]=o("作者：",-1)),e(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...t[11]||(t[11]=[o("Arindam",-1)])]),_:1}),t[16]||(t[16]=o(" 选题：",-1)),e(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[12]||(t[12]=[o("lkxed",-1)])]),_:1}),t[17]||(t[17]=o(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[13]||(t[13]=[o("geekpi",-1)])]),_:1}),t[18]||(t[18]=o(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[o("Linux中国",-1)])]),_:1}),t[23]||(t[23]=o(" 荣誉推出",-1))])])}const k=u(d,[["render",g]]);export{C as __pageData,k as default};
